def compute(vars):
    amortizable_intangible_assets = vars["v1"]
    net_assets_acquired = vars["v2"]
    if net_assets_acquired == 0:
        return None

    value = amortizable_intangible_assets / net_assets_acquired * 100
    return {
        "value": value,
        "trace": {
            "amortizable_intangible_assets": amortizable_intangible_assets,
            "net_assets_acquired": net_assets_acquired,
            "ratio": amortizable_intangible_assets / net_assets_acquired,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
